      const mode=state.ragResults.diagnostics?.mode==='basic'?t('library.basicModeShort',{},state.locale):t('library.hybridModeShort',{},state.locale);
      panel.innerHTML = `<h3>${esc(t('library.searchResults',{mode,count:results.length},state.locale))}</h3><p class="muted">${esc(state.ragResults.query)} · ${esc(t(state.ragResults.diagnostics?.mode==='basic'?'library.modeCoverage':'library.hybridCoverage',{},state.locale))}</p>${results.length ? results.map(item => `<article class="card"><h3>${esc(item.title)}</h3><p>${esc(item.text)}</p><p class="muted">${esc(item.doi || item.document_id)} · ${esc(JSON.stringify(item.locator || {}))} · ${esc(item.score)}</p><button data-evidence-id="${esc(item.evidence_id)}">查看原文定位</button></article>`).join('') : '<p class="empty">没有命中证据。</p>'}`;
