async function submitTask(){const x=state.selected,scope=captureScope(),runId=state.run?.run_id,generation=contextGeneration,raw=app.querySelector('#task-output')?.value;if(!x||!runId)return;state.writeStatus='waiting';await action(async()=>{await api.submitTask(runId,x.task_id,x.task_version,JSON.parse(raw),scope);if(!scopeIsCurrent(scope,runId,generation))return;state.tasks=list(await api.tasks(runId,scope));if(!scopeIsCurrent(scope,runId,generation))return;state.selected=null},generation);if(generation===contextGeneration){state.writeStatus=null;render()}}
async function submitReview(){const x=state.selected,scope=captureScope(),generation=contextGeneration,monitor=state.monitorId,decision=app.querySelector('#decision')?.value,note=app.querySelector('#review-note')?.value;if(!x)return;state.writeStatus='waiting';await action(async()=>{await api.decide(x.issue_id,decision,note,scope);if(!scopeIsCurrent(scope,null,generation)||state.monitorId!==monitor||state.page!=='reviews')return;state.reviews=list(await api.reviews(monitor,null,scope));if(!scopeIsCurrent(scope,null,generation)||state.monitorId!==monitor)return;state.selected=null},generation);if(generation===contextGeneration){state.writeStatus=null;render()}}
async function loadConversations(generation=contextGeneration,keepCurrent=true){const scope=captureScope(),workspace=scope.workspaceId;try{const data=await api.conversations(scope);if(generation!==contextGeneration||scope.workspaceId!==state.workspaceId)return;state.conversations=list(data).filter(x=>x.library_id===scope.libraryId&&x.collection_id===scope.collectionId);let current=keepCurrent?state.conversation:null;if(current&&!state.conversations.some(x=>x.conversation_id===current.conversation_id))current=null;if(!current&&state.conversations.length)current=state.conversations[0];state.conversation=current? (await api.conversation(current.conversation_id,scope)).conversation:null;if(state.conversation){state.chatExecutor=state.conversation.executor;state.conversations=state.conversations.map(item=>item.conversation_id===state.conversation.conversation_id?state.conversation:item)}if(generation!==contextGeneration||workspace!==state.workspaceId)return;render()}catch(e){if(generation===contextGeneration)state.error=code(e)}}
async function loadConversationScenario(){if(state.syntheticScenario)return state.syntheticScenario;const response=await fetch("/synthetic-scenario.json");if(!response.ok)throw new Error("Synthetic scenario unavailable");return await response.json()}
function executeKey(id){const key=`rh-chat-execute:${id}`;let value=localStorage.getItem(key);if(!value){value=crypto.randomUUID();localStorage.setItem(key,value)}return value}
async function switchConversationExecutor(target){const current=state.conversation;if(!current){state.chatExecutor=target;state.chatSwitchError=null;render();return}if(target===current.executor){state.chatExecutor=target;render();return}if(target==='api'&&!app.querySelector('#chat-model')){state.chatExecutor='api';state.chatSwitchError=null;render();return}const scope=captureScope(),generation=contextGeneration,id=current.conversation_id;state.chatExecutor=target;state.chatSwitchError=null;const apiConfig=target==='api'?apiConversationConfig():undefined;if(target==='api'&&(!apiConfig.model||apiConfig.max_planning_calls>apiConfig.total_model_calls)){state.chatExecutor=current.executor;state.chatSwitchError=t('chat.configErrors',{},state.locale);render();return}state.conversationBusy=true;state.conversationAction='executor';render();try{const out=await api.switchConversationExecutor(id,target,scope,executorSwitchKey(id,target,apiConfig),apiConfig);if(!scopeIsCurrent(scope,null,generation))return;if(out.conversation?.conversation_id!==id)throw new Error('Conversation identity changed during executor switch');state.conversation=out.conversation;state.chatExecutor=out.conversation.executor;if(target==='api')state.chatApiConfigs[id]=apiConfig;state.conversations=[out.conversation,...state.conversations.filter(x=>x.conversation_id!==id)]}catch(error){state.chatExecutor=current.executor;state.chatSwitchError=error instanceof ApiError&&error.code==='RH_GUI_API_CONFIG_EXPANSION'?t('chat.configExpansion',{},state.locale):error instanceof ApiError&&['RH_GUI_EXECUTOR_SWITCH_BUSY','RH_GUI_EXECUTOR_SWITCH_EXTERNAL_PENDING'].includes(error.code)?t('chat.switchBusy',{},state.locale):code(error)}finally{state.conversationBusy=false;state.conversationAction='';render()}}
function bindConversation(){app.querySelector('#chat-toggle')?.addEventListener('click',()=>{state.chatOpen=!state.chatOpen;render()});app.querySelector('#chat-list-toggle')?.addEventListener('click',()=>{state.chatListOpen=!state.chatListOpen;render()});app.querySelector('#chat-new')?.addEventListener('click',async()=>{const scope=captureScope(),generation=contextGeneration;state.conversationBusy=true;state.conversationAction='create';render();try{const executor=state.chatExecutor;const config=executor==='api'?apiConversationConfig():undefined;if(executor==='api'&&(!config.model||config.max_planning_calls>config.total_model_calls))throw new Error(t('chat.configErrors',{},state.locale));const data=await createAndReadConversation(executor,scope,config);if(!scopeIsCurrent(scope,null,generation))return;state.conversation=data.conversation;if(data.executor==='api')state.chatApiConfigs[state.conversation.conversation_id]=data.config;state.chatSwitchError=null;state.chatLinkedRuns={};state.conversations=[state.conversation,...state.conversations.filter(x=>x.conversation_id!==state.conversation.conversation_id)];render()}catch(e){state.error=code(e)}finally{state.conversationBusy=false;state.conversationAction='';render()}});app.querySelector('#chat-executor')?.addEventListener('change',e=>switchConversationExecutor(e.target.value));app.querySelector('#chat-switch-api')?.addEventListener('click',()=>switchConversationExecutor('api'));app.querySelectorAll('[data-conversation]').forEach(b=>b.onclick=async()=>{const scope=captureScope(),generation=contextGeneration;try{const data=await api.conversation(b.dataset.conversation,scope);if(!scopeIsCurrent(scope,null,generation))return;state.conversation=data.conversation;state.chatExecutor=data.conversation.executor;state.chatLinkedRuns={};render()}catch(e){state.error=code(e);render()}});app.querySelector('#chat-form')?.addEventListener('submit',async e=>{e.preventDefault();const content=app.querySelector('#chat-input')?.value.trim();if(!content)return;const scope=captureScope(),generation=contextGeneration,draftKey=conversationScopeKey(captureScope(),state.conversation?.conversation_id||'draft');const requestedExecutor=app.querySelector('#chat-executor')?.value||'scripted';if(state.conversation&&requestedExecutor!==state.conversation.executor){state.chatSwitchError=t('chat.switchBeforeSend',{},state.locale);render();return}const selectedExecutor=state.conversation?.executor||requestedExecutor;if(selectedExecutor==='api'){const config=apiConversationConfig();if(!config.model||config.max_planning_calls>config.total_model_calls){state.chatSwitchError=t('chat.configErrors',{},state.locale);render();return}if(!confirm(t('chat.planConfirm',{count:config.max_planning_calls},state.locale)))return}state.chatDrafts.set(draftKey,content);state.pendingTurn=stableTurnIdentity(content,scope,state.pendingTurn);state.conversationBusy=true;state.conversationAction='turn';render();try{if(!state.conversation){const executor=app.querySelector('#chat-executor')?.value||'scripted';const config=executor==='api'?apiConversationConfig():undefined;if(executor==='api'&&(!config.model||config.max_planning_calls>config.total_model_calls))throw new Error(t('chat.configErrors',{},state.locale));const created=await createAndReadConversation(executor,scope,config);state.conversation=created.conversation;state.chatExecutor=created.executor;if(created.executor==='api')state.chatApiConfigs[state.conversation.conversation_id]=created.config}const data=await api.conversationTurn(state.conversation.conversation_id,content,state.pendingTurn.requestId,scope);if(!scopeIsCurrent(scope,null,generation))return;state.conversation=data.conversation;state.chatExecutor=data.conversation.executor;state.chatSwitchError=null;state.chatDrafts.delete(draftKey);state.pendingTurn=null;state.conversations=[state.conversation,...state.conversations.filter(x=>x.conversation_id!==state.conversation.conversation_id)];await loadConversations(generation)}catch(err){if(generation===contextGeneration)state.error=code(err)}finally{state.conversationBusy=false;state.conversationAction='';render()}});app.querySelector('#chat-execute')?.addEventListener('click',async()=>{const scope=captureScope(),generation=contextGeneration,id=state.conversation?.conversation_id;if(!id)return;if(state.conversation.executor==='api'&&!confirm(t('chat.executeConfirm',{count:state.conversation.api?.remaining_model_calls??'UNKNOWN'},state.locale)))return;state.conversationBusy=true;state.conversationAction='execute';render();try{const out=await api.executeConversation(id,state.conversation.executor,state.conversation.executor==='api'?await loadConversationScenario():undefined,scope,executeKey(id));if(!scopeIsCurrent(scope,null,generation))return;state.conversation=out.conversation;render();for(let i=0;i<180;i++){await new Promise(resolve=>setTimeout(resolve,1000));if(!scopeIsCurrent(scope,null,generation))return;const latest=(await api.conversation(id,scope)).conversation;state.conversation=latest;state.conversations=[latest,...state.conversations.filter(x=>x.conversation_id!==id)];if(['completed','partial','failed','stopped','policy_blocked'].includes(latest.status)){const [run,tasks,artifacts]=await Promise.allSettled([api.run(latest.run_id,scope),api.tasks(latest.run_id,scope),api.artifacts(latest.run_id,scope)]);if(run.status==='fulfilled')state.chatReport=run.value;if(tasks.status==='fulfilled')state.chatTasks=list(tasks.value);if(artifacts.status==='fulfilled')state.chatArtifacts=list(artifacts.value)}render();if(['completed','partial','failed','stopped','policy_blocked'].includes(latest.status))break}}catch(err){if(generation===contextGeneration)state.error=code(err)}finally{state.conversationBusy=false;state.conversationAction='';render()}});for(const [id,kind] of [['chat-stop-reply','reply'],['chat-stop-investigation','investigation']])app.querySelector(`#${id}`)?.addEventListener('click',async()=>{const scope=captureScope(),generation=contextGeneration;if(!state.conversation)return;try{const out=await api.stopConversation(state.conversation.conversation_id,kind,scope);if(scopeIsCurrent(scope,null,generation)){state.conversation=out.conversation;if(kind==='reply'){state.conversationBusy=false;state.conversationAction=''}render()}}catch(e){state.error=code(e);render()}});app.querySelectorAll('[data-chat-run]').forEach(b=>b.onclick=async()=>{const scope=captureScope(),generation=contextGeneration,id=b.dataset.chatRun;try{const run=await api.run(id,scope);if(!scopeIsCurrent(scope,id,generation))return;state.run=run;state.page='report';await loadReportData(generation);render()}catch(e){state.error=code(e);render()}})}
const observingRuns=new Set();
async function subscribeControl(){const scope=captureScope();try{await api.control('view.subscribe',{client_id:state.clientId},scope);state.controlSeq=0;state.controlNotices=[]}catch(error){if(error instanceof ApiError&&error.status===403)state.controlSeq=0}}
async function refreshExternalConversation(){const c=state.conversation;if(!state.scopeReady||c?.executor!=='external'||!['waiting_external','external_working','external_reply_ready'].includes(c.status))return;const scope=captureScope(),id=c.conversation_id,generation=contextGeneration;try{const latest=(await api.conversation(id,scope)).conversation;if(generation!==contextGeneration||state.conversation?.conversation_id!==id)return;const changed=JSON.stringify(latest)!==JSON.stringify(c);state.conversation=latest;state.conversations=[latest,...state.conversations.filter(x=>x.conversation_id!==id)];const refs=[...(latest.tool_results||[]).map(x=>x.object_refs||{}),...(latest.messages||[]).map(x=>x.refs||{})];for(const runId of new Set(refs.map(x=>x.run_id).filter(Boolean))){const commandId=refs.find(x=>x.run_id===runId)?.command_id;try{const run=await api.run(runId,scope);let command=null;if(commandId)try{command=await api.command(commandId,scope)}catch{}state.chatLinkedRuns[runId]={...run,command}}catch{}}if(changed)render()}catch{}}
async function pollControl(generation=contextGeneration){const scope=captureScope();try{const data=await api.controlEvents(state.clientId,state.controlSeq,scope);if(generation!==contextGeneration||!scopeIsCurrent(scope,null,generation))return;state.controlSeq=data.next_seq??state.controlSeq;const notices=(data.events||[]).filter(event=>event.type==='navigate'&&event.target?.workspace_id===scope.workspaceId).map(event=>({seq:event.seq,target:event.target,scope:{...scope}}));if(notices.length){const known=new Set(state.controlNotices.map(item=>item.seq));state.controlNotices=[...state.controlNotices,...notices.filter(item=>!known.has(item.seq))].slice(-5);render()}}catch(error){if(error instanceof ApiError&&error.status===404){await subscribeControl();return}if(error instanceof ApiError&&error.status===403){await subscribeControl()}}}
async function openControlNotice(seq){const notice=state.controlNotices.find(item=>item.seq===Number(seq));if(!notice)return;const scope=captureScope(),target=notice.target,generation=++contextGeneration;if(target.workspace_id!==scope.workspaceId||notice.scope?.workspaceId!==scope.workspaceId||notice.scope?.libraryId!==scope.libraryId||notice.scope?.collectionId!==scope.collectionId){state.controlNotices=state.controlNotices.filter(item=>item.seq!==notice.seq);state.error=t('control.scopeMismatch',{},state.locale);render();return}await action(async()=>{let verifiedRun=null;if(target.run_id){verifiedRun=await api.run(target.run_id,scope);if(!scopeIsCurrent(scope,null,generation))return}if(target.page==='evidence'){if(!target.evidence_id)throw new Error(t('control.invalidTarget',{},state.locale));if(verifiedRun)state.run=verifiedRun;state.controlNotices=state.controlNotices.filter(item=>item.seq!==notice.seq);await openEvidence(target.evidence_id);return}else if(target.page==='run'||target.page==='report'){if(!verifiedRun)throw new Error(t('control.invalidTarget',{},state.locale));state.run=verifiedRun;state.tasks=list(await api.tasks(verifiedRun.run_id,scope));if(!scopeIsCurrent(scope,verifiedRun.run_id,generation))return;state.page=target.page==='report'?'report':'runs';if(state.page==='report')await loadReportData(generation)}else if(target.page==='queue'){state.page='settings';await loadQueue(generation)}else throw new Error(t('control.invalidTarget',{},state.locale));state.controlNotices=state.controlNotices.filter(item=>item.seq!==notice.seq)},generation)}
async function syncEvents(generation=contextGeneration,runId=state.run?.run_id,scope=captureScope()){if(!runId||state.caps.events!==true)return;const observerKey=`${scope.workspaceId}:${runId}`;if(observingRuns.has(observerKey))return;observingRuns.add(observerKey);const oldSeq=state.eventSeq,oldConnection=state.connection;try{let data;try{data=await api.events(runId,state.eventSeq,scope)}catch(e){if(e instanceof ApiError&&e.status===409){const run=await api.run(runId,scope);if(generation!==contextGeneration||state.run?.run_id!==runId)return;state.run=run;state.eventSeq=0;state.events=[];data=await api.events(runId,0,scope)}else throw e}if(generation!==contextGeneration||state.run?.run_id!==runId||scope.workspaceId!==state.workspaceId)return;state.run=data.snapshot;state.eventSeq=data.next_seq;state.events.push(...data.events);state.events=state.events.slice(-20);state.connection='已连接 · '+data.transport;runViews.set(`${scope.workspaceId}:${runId}`,{run:state.run,tasks:state.tasks,events:state.events,eventSeq:state.eventSeq,connection:state.connection})}catch(e){if(generation===contextGeneration&&state.run?.run_id===runId)state.connection='连接中断：'+code(e)}finally{observingRuns.delete(observerKey);if(generation===contextGeneration&&(oldSeq!==state.eventSeq||oldConnection!==state.connection))render()}}
async function refreshSelectedRun(generation=contextGeneration){const runId=state.run?.run_id;if(!runId)return;const scope=captureScope();try{const [run,tasks]=await Promise.all([api.run(runId,scope),api.tasks(runId,scope)]);if(!scopeIsCurrent(scope,runId,generation))return;const changed=JSON.stringify(run)!==JSON.stringify(state.run)||JSON.stringify(list(tasks))!==JSON.stringify(state.tasks);state.run=run;state.tasks=list(tasks);if(changed&&state.page==='report')await loadReportData(generation);if(changed)render()}catch{}}
setInterval(()=>{const generation=contextGeneration;if(state.scopeReady){pollControl(generation);refreshExternalConversation()}if(state.run){refreshSelectedRun(generation);if(state.caps.events===true)syncEvents(generation)}loadQueue(generation)},3000);
async function initialize(){const generation=++contextGeneration;await action(async()=>{const registry=await api.registry();if(generation!==contextGeneration)return;state.registry=registry;const workspaces=registry.workspaces||[];if(!workspaces.length){state.scopeReady=false;return}let workspace=workspaces.find(x=>x.workspace_id===state.workspaceId);if(!workspace){workspace=workspaces[0];state.workspaceId=workspace.workspace_id}let library=workspace.libraries?.find(x=>x.library_id===state.libraryId)||workspace.libraries?.find(x=>x.library_id===workspace.default_library_id)||workspace.libraries?.[0];if(!library){state.scopeReady=false;return}state.libraryId=library.library_id;const collections=library.collections||[];if(!collections.some(x=>x.collection_id===state.collectionId))state.collectionId=collections.some(x=>x.collection_id==='all')?'all':collections[0]?.collection_id||'all';localStorage.setItem('rh-workspace',state.workspaceId);localStorage.setItem('rh-library',state.libraryId);localStorage.setItem('rh-collection',state.collectionId);setScope({workspaceId:state.workspaceId,libraryId:state.libraryId,collectionId:state.collectionId});const context=await api.contexts();if(generation!==contextGeneration)return;state.contextData=context;state.scopeReady=true;state.caps=(await api.capabilities()).capabilities;await Promise.all([loadLibrary(generation),loadQueue(generation)]);await loadOverview(generation)},generation)}await initialize();if(state.scopeReady){await subscribeControl();await loadConversations(contextGeneration,false)}






